challenge.code:
const P = ctx.params;
const shell = ctx.chip('render root', { color: ctx.colors.g2, minWidth: 180, size: 13 });
shell.y = ctx.height - 30;
shell.x = ctx.width / 2;
ctx.stage.addChild(shell);
ctx.app.stage.on('pointermove', (e) => { shell.x = Math.max(70, Math.min(ctx.width - 70, e.global.x)); });
let rooted = false, banked = 0, t = 30, spawned = 0;
const live = [];
ctx.api.setGoal('catch $app(page) first');
ctx.onTick((dt) => {
  t += dt;
  if (t > 44) {
    t = 0;
    const wantRoot = !rooted && spawned % 3 === 1;
    const label = wantRoot ? '$app(page)' : ctx.pick(P.lines);
    const c = ctx.chip(label, { color: wantRoot ? ctx.colors.g1 : ctx.colors.g3, textColor: 0x04101a, size: 13 });
    c.x = ctx.rand(70, ctx.width - 70);
    c.y = -20;
    c.isRoot = wantRoot;
    ctx.stage.addChild(c);
    live.push(c);
    spawned++;
  }
  for (let i = live.length - 1; i >= 0; i--) {
    const c = live[i];
    c.y += 2.3 * dt;
    const hit = c.y > shell.y - 22 && c.y < shell.y + 22 && Math.abs(c.x - shell.x) < 105;
    if (hit) {
      live.splice(i, 1);
      if (c.isRoot) {
        rooted = true;
        ctx.api.setGoal('root locked - bank 5 statements');
        gsap.to(shell.scale, { x: 1.3, y: 1.3, duration: .12, onComplete: () => gsap.to(shell.scale, { x: 1, y: 1, duration: .2, ease: 'back.out' }) });
      } else if (!rooted) {
        c.destroy();
        ctx.api.fail('A leaf landed before the shell. $app(...) has to commit first.');
        return;
      } else {
        banked++;
        ctx.api.setScore(banked);
        if (banked >= 5) ctx.api.win('Shell first, leaves after. That is streaming.');
      }
      c.destroy();
      continue;
    }
    if (c.y > ctx.height + 30) {
      live.splice(i, 1);
      c.destroy();
    }
  }
});

