challenge.code:
const P = ctx.params;
const laneY = ctx.height - 56;
const binL = ctx.chip('REACTIVE', { color: ctx.colors.g1, textColor: 0x04101a, size: 12, minWidth: 132 });
const binR = ctx.chip('INERT', { color: ctx.colors.dim, textColor: 0xdfe6ff, size: 12, minWidth: 132 });
const rail = new PIXI.Graphics();
ctx.stage.addChild(rail, binL, binR);
let aim = ctx.width / 2, score = 0, strikes = 0, done = false, tok = null;
ctx.app.stage.on('pointermove', (e) => { aim = e.global.x; });
ctx.app.stage.on('pointerdown', (e) => { aim = e.global.x; });
function layout() {
  const m = ctx.width / 2;
  binL.x = m / 2; binL.y = ctx.height - 24;
  binR.x = m + m / 2; binR.y = ctx.height - 24;
  rail.clear();
  rail.moveTo(m, 10).lineTo(m, laneY).stroke({ width: 2, color: ctx.colors.g3, alpha: .3 });
  rail.moveTo(14, laneY).lineTo(ctx.width - 14, laneY).stroke({ width: 1, color: ctx.colors.ink, alpha: .2 });
}
function spawn() {
  const hot = Math.random() < .5;
  tok = ctx.chip(ctx.pick(hot ? P.reactive : P.inert), { color: ctx.colors.g2, textColor: 0x04101a, size: 14 });
  tok.hot = hot;
  tok.x = ctx.width / 2;
  tok.y = -22;
  ctx.stage.addChild(tok);
}
layout();
ctx.api.setGoal('0 / ' + P.target);
spawn();
ctx.onTick((dt) => {
  if (done || !tok) return;
  layout();
  const m = ctx.width / 2;
  tok.x += (aim - tok.x) * Math.min(0.9, 0.16 * dt);
  tok.x = Math.max(54, Math.min(ctx.width - 54, tok.x));
  tok.y += (1.6 + score * 0.14) * dt;
  if (tok.y < laneY) return;
  const left = tok.x < m;
  const ok = left === tok.hot;
  const bin = left ? binL : binR;
  gsap.to(bin.scale, { x: 1.14, y: 1.14, duration: .1, onComplete: () => gsap.to(bin.scale, { x: 1, y: 1, duration: .22, ease: 'back.out' }) });
  const puff = ctx.glow(42, ok ? ctx.colors.good : ctx.colors.bad, .95);
  puff.x = tok.x; puff.y = laneY;
  ctx.stage.addChild(puff);
  gsap.to(puff, { alpha: 0, duration: .55, onComplete: () => { if (!puff.destroyed) puff.destroy(); } });
  const name = tok.label;
  tok.destroy();
  tok = null;
  if (ok) { score++; ctx.api.setScore(score); ctx.api.setGoal(score + ' / ' + P.target); }
  else { strikes++; }
  if (!ok && strikes >= 3) { done = true; ctx.api.fail('Three misfiled. ' + name + ' belonged in the other bin - only the $ decides.'); return; }
  if (score >= P.target) { done = true; ctx.api.win('Sorted. let and const are noise; the sigil is the mechanism.'); return; }
  spawn();
});

