challenge.code:
const P = ctx.params;
const W = ctx.width, H = ctx.height;
const R = P.regions;
const g = new PIXI.Graphics();
ctx.stage.addChild(g);
const kicker = ctx.text('THIS REGION NEEDS', { size: 10, color: ctx.colors.dim, weight: '700' });
kicker.anchor.set(.5); kicker.x = W / 2; kicker.y = 24;
ctx.stage.addChild(kicker);
const need = ctx.text(R[0].need, { size: 14, color: ctx.colors.ink });
need.anchor.set(.5); need.x = W / 2; need.y = 43;
ctx.stage.addChild(need);
const state = [];
for (let i = 0; i < R.length; i++) state.push(0);
let idx = 0, score = 0, misses = 0, t = P.seconds, done = false;
function draw() {
  g.clear();
  g.roundRect(16, 12, W - 32, H - 128, 10).stroke({ width: 1, color: ctx.colors.dim, alpha: .45 });
  for (let i = 0; i < R.length; i++) {
    const y = 64 + i * 24;
    const live = i === idx && !done;
    g.roundRect(30, y, W - 60, 20, 5).fill({ color: 0x0a1523, alpha: live ? .95 : .55 }).stroke({ width: live ? 2 : 1, color: live ? ctx.colors.g1 : ctx.colors.dim, alpha: live ? 1 : .35 });
    if (state[i] === 1) {
      g.roundRect(38, y + 5, 42, 4, 2).fill({ color: ctx.colors.g2 });
      g.roundRect(88, y + 5, W - 190, 4, 2).fill({ color: ctx.colors.g3, alpha: .75 });
      g.roundRect(38, y + 12, W - 140, 3, 2).fill({ color: ctx.colors.g1, alpha: .4 });
    } else if (state[i] === -1) {
      g.roundRect(38, y + 9, 54, 2, 1).fill({ color: ctx.colors.bad, alpha: .85 });
    }
  }
  if (!done) {
    g.roundRect(30, H - 106, W - 60, 3, 2).fill({ color: ctx.colors.dim, alpha: .3 });
    const w = Math.max(0, (W - 60) * (t / P.seconds));
    g.roundRect(30, H - 106, w, 3, 2).fill({ color: t < P.seconds * .35 ? ctx.colors.warn : ctx.colors.g2 });
  }
}
function advance() {
  ctx.api.setGoal(score + ' / ' + P.target);
  if (score >= P.target) { done = true; draw(); ctx.api.win('Every region filled by a single composite.'); return; }
  if (misses >= 3) { done = true; draw(); ctx.api.fail('Three regions shipped sparse. Reach for the composite that owns the job.'); return; }
  idx++;
  if (idx >= R.length) { done = true; draw(); ctx.api.fail('Out of regions - two of them rendered as wireframe.'); return; }
  t = P.seconds;
  need.text = R[idx].need;
  draw();
}
function pick(name, chip) {
  if (done) return;
  gsap.to(chip.scale, { x: 1.1, y: 1.1, duration: .1, onComplete: () => gsap.to(chip.scale, { x: 1, y: 1, duration: .18, ease: 'back.out' }) });
  if (name === R[idx].answer) { state[idx] = 1; score++; ctx.api.setScore(score); }
  else { state[idx] = -1; misses++; }
  advance();
}
const cw = (W - 44) / 3;
P.options.forEach((name, i) => {
  const c = ctx.chip(name, { color: 0x101d33, textColor: 0xd8e6ff, stroke: ctx.colors.g3, size: 12, minWidth: cw - 12 });
  c.x = 22 + cw * (i % 3) + cw / 2;
  c.y = H - 76 + Math.floor(i / 3) * 34;
  c.eventMode = 'static';
  c.cursor = 'pointer';
  c.hitArea = new PIXI.Rectangle(-cw / 2, -15, cw, 30);
  c.on('pointertap', () => pick(name, c));
  ctx.stage.addChild(c);
});
ctx.api.setScore(0);
ctx.api.setGoal('0 / ' + P.target);
draw();
ctx.onTick((dt) => {
  if (done) return;
  t -= dt / 60;
  if (t <= 0) { state[idx] = -1; misses++; advance(); return; }
  draw();
});

