challenge.code:
const P = ctx.params;
const cx = ctx.width / 2, cy = ctx.height / 2 - 4;
const R = Math.max(74, Math.min(cx - 84, 112));

const ring = new PIXI.Graphics();
ring.circle(cx, cy, R).stroke({ width: 1.5, color: ctx.colors.g3, alpha: .28 });
ring.circle(cx, cy, R + 30).stroke({ width: 1, color: ctx.colors.g3, alpha: .1 });
ctx.stage.addChild(ring);

const core = new PIXI.Container();
core.x = cx; core.y = cy;
core.addChild(ctx.glow(96, ctx.colors.g2, .85));
core.addChild(ctx.chip('$effect(fn, [ ])', { color: ctx.colors.g2, textColor: 0x1a0620, size: 13, minWidth: 140 }));
ctx.stage.addChild(core);

const gate = ctx.text('GATE', { size: 10, color: ctx.colors.g3 });
gate.anchor.set(.5); gate.x = cx; gate.y = cy - R - 22;
ctx.stage.addChild(gate);

const banner = ctx.text('tap a token to admit it', { size: 11, color: ctx.colors.dim });
banner.anchor.set(.5); banner.x = cx; banner.y = ctx.height - 14;
ctx.stage.addChild(banner);

let score = 0, missed = 0, dead = false, t = 999;
const live = [];
ctx.api.setScore(0);
ctx.api.setGoal('0 / ' + P.target);

function errFor(label) {
  if (label.charAt(0) === '"') return 'Unknown effect dependency string ' + label;
  return 'Unexpected Identifier "' + label.split('.')[0] + '" inside effect dependency array';
}

function say(msg, color) { banner.text = msg; banner.style.fill = color; }

function admit(tok) {
  if (dead || tok.gone) return;
  tok.gone = true;
  const i = live.indexOf(tok);
  if (i >= 0) live.splice(i, 1);
  const n = tok.node;
  n.eventMode = 'none';
  if (tok.legal) {
    score++;
    ctx.api.setScore(score);
    ctx.api.setGoal(score + ' / ' + P.target);
    say('admitted  ' + tok.label, ctx.colors.g1);
    gsap.to(n, { x: cx, y: cy, alpha: 0, duration: .32, ease: 'power2.in', onComplete: () => n.destroy() });
    gsap.to(core.scale, { x: 1.15, y: 1.15, duration: .12, onComplete: () => gsap.to(core.scale, { x: 1, y: 1, duration: .26, ease: 'back.out' }) });
    if (score >= P.target) { dead = true; ctx.api.win('Only atoms and tokens got through.'); }
  } else {
    dead = true;
    const g = new PIXI.Graphics();
    g.moveTo(-56, -20).lineTo(-16, 4).lineTo(-30, 22).stroke({ width: 3, color: ctx.colors.bad });
    g.moveTo(14, -22).lineTo(34, 2).lineTo(20, 24).stroke({ width: 3, color: ctx.colors.bad });
    core.addChild(g);
    say(errFor(tok.label), ctx.colors.bad);
    gsap.to(n, { x: cx, y: cy, alpha: 0, duration: .2, onComplete: () => n.destroy() });
    ctx.api.fail(errFor(tok.label));
  }
}

function spawn() {
  const legal = Math.random() < .55;
  const label = ctx.pick(legal ? P.legal : P.illegal);
  const c = ctx.chip(label, { size: 12, color: legal ? ctx.colors.g1 : 0x241a33, textColor: legal ? 0x1a0620 : 0xf6ecff, stroke: legal ? 0 : ctx.colors.bad });
  c.eventMode = 'static';
  c.cursor = 'pointer';
  c.hitArea = new PIXI.Rectangle(-c.chipWidth / 2 - 4, -c.chipHeight / 2 - 4, c.chipWidth + 8, c.chipHeight + 8);
  c.alpha = 0;
  const tok = { node: c, label: label, legal: legal, ang: ctx.rand(0, Math.PI * 2), spd: ctx.rand(.010, .015) * (Math.random() < .5 ? 1 : -1), life: 0, gone: false };
  c.x = cx + Math.cos(tok.ang) * R;
  c.y = cy + Math.sin(tok.ang) * R;
  c.on('pointertap', () => admit(tok));
  ctx.stage.addChild(c);
  live.push(tok);
  gsap.to(c, { alpha: 1, duration: .3 });
}

ctx.onTick((dt) => {
  if (dead) return;
  t += dt;
  if (t > 44 && live.length < P.maxLive) { t = 0; spawn(); }
  for (let i = live.length - 1; i >= 0; i--) {
    const tok = live[i];
    tok.ang += tok.spd * dt;
    tok.life += dt;
    tok.node.x = cx + Math.cos(tok.ang) * R;
    tok.node.y = cy + Math.sin(tok.ang) * R;
    if (tok.life > 320) {
      live.splice(i, 1);
      tok.gone = true;
      const n = tok.node;
      gsap.to(n, { alpha: 0, duration: .3, onComplete: () => n.destroy() });
      if (tok.legal) {
        missed++;
        say('a legal dependency drifted past  (' + missed + ' / 3)', ctx.colors.warn);
        if (missed >= 3) { dead = true; ctx.api.fail('Three legal dependencies drifted past the gate.'); }
      }
    }
  }
});

