challenge.code:
const P = ctx.params;
const url = ctx.text('', { size: 19, color: ctx.colors.g1 });
url.anchor.set(.5); url.x = ctx.width / 2; url.y = 32;
ctx.stage.addChild(url);
const sub = ctx.text('the URL is arriving', { size: 11, color: ctx.colors.dim });
sub.anchor.set(.5); sub.x = ctx.width / 2; sub.y = 56;
ctx.stage.addChild(sub);
let live = [], idx = 0, score = 0, miss = 0, typed = 0, full = '', armed = false, pending = 0;
ctx.api.setScore(0);
ctx.api.setGoal('0 / ' + P.target);
function round() {
  for (const c of live) c.destroy();
  live = []; typed = 0; armed = false; pending = 0;
  sub.text = 'the URL is arriving';
  const r = P.rounds[idx % P.rounds.length];
  idx++;
  full = r.url;
  const arms = r.arms.slice();
  for (let i = arms.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0; const t = arms[i]; arms[i] = arms[j]; arms[j] = t; }
  for (let i = 0; i < arms.length; i++) {
    const c = ctx.chip(arms[i], { color: 0x121a2b, textColor: 0xdfe6ff, stroke: ctx.colors.g3, size: 13, minWidth: 132 });
    c.x = -100 - i * ctx.rand(130, 220);
    c.y = 100 + i * 46;
    c.good = arms[i] === r.answer;
    c.eventMode = 'static';
    c.cursor = 'pointer';
    c.on('pointertap', () => tap(c));
    ctx.stage.addChild(c);
    live.push(c);
  }
}
function tap(c) {
  if (!armed || pending) return;
  if (c.good) {
    score++;
    ctx.api.setScore(score);
    ctx.api.setGoal(score + ' / ' + P.target);
    armed = false;
    sub.text = 'matched';
    gsap.to(c.scale, { x: 1.25, y: 1.25, duration: .12, onComplete: () => gsap.to(c.scale, { x: 1, y: 1, duration: .2, ease: 'back.out' }) });
    if (score >= P.target) { ctx.api.win('First match wins - and you found it every time.'); return; }
    pending = 34;
  } else {
    miss++;
    c.eventMode = 'none';
    gsap.to(c, { alpha: .2, duration: .25 });
    sub.text = 'that arm cannot match - ' + (3 - miss) + ' left';
    if (miss >= 3) ctx.api.fail('Three arms that could not match. A :param eats one segment, never a slash.');
  }
}
round();
ctx.onTick((dt) => {
  if (pending > 0) { pending -= dt; if (pending <= 0) { pending = 0; round(); } return; }
  if (!armed) {
    typed += .38 * dt;
    const n = Math.min(full.length, typed | 0);
    url.text = full.slice(0, n) + (n < full.length ? '_' : '');
    if (n >= full.length) { armed = true; sub.text = 'tap the arm the router would pick'; }
  }
  for (let i = 0; i < live.length; i++) {
    const c = live[i];
    c.x += 1.45 * dt;
    if (c.x > ctx.width + 100) c.x = -100;
  }
});

